import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>PNG'den WebP'ye dönüştürmek, bir web sitesini hızlandırmanın en kolay yollarından biridir. Aynı görsel, aynı görünüm, çok daha küçük bir dosya; üstelik şeffaflık kaybolmaz.</p>\n<p>PNG, keskin çizgiler ve saydam arka planlar için harikadır ama dosyaları büyüktür. WebP aynı işi çok daha az baytla yapar ve modern tarayıcıların tamamı onu destekler.</p>\n<p>Bu kılavuz, dönüştürmenin nasıl çalıştığını, ne kadar kazandırdığını ve logolar, simgeler, ekran görüntüleri ile ana görseller için hangi ayarların işe yaradığını anlatıyor.</p>\n<h2 id=\"what-is-png-to-webp\">PNG'den WebP'ye dönüştürme nedir?</h2>\n<p>PNG'den WebP'ye dönüştürme, kayıpsız bir PNG dosyasını alıp WebP biçiminde yeniden kodlamaktır. Pikseller aynı kalır; değişen yalnızca dosyanın saklanma biçimidir.</p>\n<p>WebP, PNG'den daha akıllı sıkıştırma kullanır. Düz renk alanlarını ve tekrarlayan desenleri daha verimli kodlar, bu yüzden dosya belirgin biçimde küçülür.</p>\n<p>Dönüştürme tarayıcıda yapılır; dosyanız cihazınızdan ayrılmaz. Birkaç saniye içinde aynı görselin çok daha hafif bir kopyasını indirirsiniz.</p>\n<h2 id=\"how-much-smaller\">WebP, PNG'den ne kadar daha küçük?</h2>\n<p>Çoğu PNG, WebP olarak yüzde 25 ila 35 daha küçük olur. 1 MB'lık bir PNG genellikle 650-750 KB'lık bir WebP'ye dönüşür.</p>\n<p>Düz renkli logolar ve simgeler daha da fazla küçülür. Az renkli, geniş düz alanlı bir logo bazen yüzde 50'den fazla küçülebilir.</p>\n<p>Fotoğraf benzeri karmaşık PNG'ler daha az kazandırır. Yine de yüzde 20 civarı kazanç, onlarca görseli olan bir sitede toplamda büyük fark yaratır.</p>\n<h2 id=\"transparency-preserved\">Şeffaflık korunur</h2>\n<p>WebP, PNG gibi alfa kanalını destekler. Saydam arka planlı bir logo, dönüştürmeden sonra da saydam kalır.</p>\n<p>Bu, WebP'yi logolar ve simgeler için güvenli kılar. Arka planın saydam kalacağından emin olabilirsiniz; beyaz bir kutu sürprizi yaşamazsınız.</p>\n<p>Dönüştürmeden sonra saydamlığı kontrol edin. Saydam alanları gösteren bir önizlemede köşelerin temiz kaldığını doğrulayın; sorun görürseniz orijinal PNG'yi koruyun.</p>\n<h2 id=\"quality-settings\">İşe yarayan kalite ayarları</h2>\n<p>Logolar ve simgeler için kaliteyi yüzde 85 civarında tutun. Keskin kenarlar korunur ve dosya yine de PNG'den çok daha küçük olur.</p>\n<p>Ekran görüntüleri için yüzde 80 yeterlidir. Metin okunaklı kalır ve dosya boyutu belirgin biçimde düşer.</p>\n<p>Fotoğraf içeren PNG'ler için yüzde 75-80 deneyin. Kalite kaybı çıplak gözle fark edilmez ama kazanç büyüktür; önce önizlemeyle karşılaştırın.</p>\n<h2 id=\"icon-sets\">Simge setlerinin tamamını dönüştürmek</h2>\n<p>Bir simge setini tek tek dönüştürmek zaman kaybıdır. Tüm PNG'leri aynı anda yükleyin ve tek seferde WebP'ye çevirin.</p>\n<p>Toplu dönüştürmede tüm simgeler için aynı kalite ayarını kullanın. Tutarlılık, setin her yerde aynı görünmesini sağlar.</p>\n<p>Dönüştürmeden sonra dosya adlarını aynı tutun, yalnızca uzantıyı değiştirin. Kodunuzda ya da stil dosyanızda referansları güncellemek çok daha kolay olur.</p>\n<h2 id=\"screenshots-with-text\">Metin içeren ekran görüntüleri</h2>\n<p>Ekran görüntüleri WebP'de iyi görünür ama metin kenarları hassastır. Kaliteyi çok düşürürseniz yazılar bulanıklaşır.</p>\n<p>Metinli ekran görüntüleri için kaliteyi yüzde 85'in altına indirmeyin. Bu seviyede yazılar keskin kalır ve dosya yine de küçülür.</p>\n<p>Dönüştürmeden önce ve sonra yüzde 100 yakınlaştırmayla karşılaştırın. Küçük yazılardaki bulanıklık ancak tam boyutta belli olur.</p>\n<h2 id=\"hero-images\">Web siteleri için ana görseller</h2>\n<p>Ana görseller sayfanın en büyük dosyalarıdır ve WebP burada en çok kazandırır. Büyük bir PNG ana görsel, WebP olarak yarıya inebilir.</p>\n<p>Ana görselde kaliteyi yüzde 80-85 arasında tutun. Ziyaretçi farkı görmez ama sayfa belirgin biçimde hızlı yüklenir.</p>\n<p>Ana görsel için her zaman yedek düşünün. Çok eski tarayıcılar WebP göstermeyebilir; picture öğesiyle JPG yedeği sunmak bu riski ortadan kaldırır.</p>\n<h2 id=\"metadata-and-colour\">Meta veriler ve renk profilleri</h2>\n<p>PNG dosyaları genellikle EXIF ya da renk profili taşımaz; WebP de taşımaz. Dönüştürmede renk kayması yaşanmaz.</p>\n<p>Bazı PNG'ler gömülü renk profili içerir. WebP'ye dönüştürmede profil genellikle korunur; renkler aynı kalır.</p>\n<p>Marka renkleri kritikse dönüştürmeden sonra kontrol edin. Logo rengini orijinalle yan yana karşılaştırın; fark görürseniz PNG'yi koruyun.</p>\n<h2 id=\"when-webp-is-larger\">WebP daha büyük çıktığında</h2>\n<p>Bazen WebP, PNG'den daha büyük çıkar. Çok küçük dosyalar ve az renkli minik simgelerde WebP'nin başlık bilgisi PNG'yi geçebilir.</p>\n<p>Birkaç KB'lık simgelerde fark önemsizdir ama yine de kontrol edin. Dönüştürülen dosya orijinalden büyükse PNG'yi saklayın.</p>\n<p>Gürültülü, grenli PNG'ler de kötü sıkışır. Rastgele pikseller WebP'nin verimli kodlayamadığı veridir; böyle dosyalarda PNG daha küçük kalabilir.</p>\n<h2 id=\"png-vs-jpg-decision\">PNG'den WebP'ye mi, PNG'den JPG'ye mi?</h2>\n<p>Şeffaflık gerekiyorsa WebP'yi seçin. JPG saydamlığı desteklemez; saydam logonun JPG'si beyaz arka planla gelir.</p>\n<p>Şeffaflık gerekmiyor ve görsel fotoğrafsa JPG de olur. Yine de WebP genellikle JPG'den de küçüktür.</p>\n<p>Hedef form ya da eski bir sistemse JPG'yi seçin. Uyumluluk, boyut kazancından önemlidir; web içinse WebP önde gider.</p>\n<h2 id=\"checking-quality\">İndirmeden önce kaliteyi kontrol etmek</h2>\n<p>Her zaman önizlemeyle karşılaştırın. Orijinal PNG ile dönüştürülen WebP'yi yan yana açın ve kenarlara, metne ve renk geçişlerine bakın.</p>\n<p>Yüzde 100 yakınlaştırmada inceleyin. Küçük resimde gizlenen kusurlar tam boyutta ortaya çıkar; özellikle ince çizgiler ve küçük yazılar risklidir.</p>\n<p>Şüphede kalırsanız kaliteyi beş puan artırın. Birkaç KB fazladan boyut, bozuk bir logodan her zaman iyidir.</p>\n<h2 id=\"common-mistakes\">Kaçınılması gereken yaygın hatalar</h2>\n<p>En yaygın hata, orijinal PNG'leri silmektir. WebP'den PNG'ye dönüş kalite kaybettirir; orijinalleri her zaman saklayın.</p>\n<p>Bir başka hata, her PNG'yi körü körüne dönüştürmektir. Çok küçük simgelerde kazanç yoktur; yalnızca işe yarayanları dönüştürün.</p>\n<p>Kaliteyi çok düşük ayarlamak da hatadır. Yüzde 60'ın altındaki kalite logolarda kenar bozulması yapar; yüzde 80-85 güvenli bölgedir.</p>\n<h2 id=\"webp-for-website-logos\">Web sitesi logoları için WebP</h2>\n<p>Logolar WebP'nin en iyi kullanım alanıdır. Keskin kenarlar, düz renkler ve saydamlık; üçü de WebP'de mükemmel korunur.</p>\n<p>Logo için kaliteyi yüzde 85-90 arasında tutun. Dosya küçülür ama marka işareti piksel piksel aynı kalır.</p>\n<p>Logonun koyu ve açık zemin sürümlerini ayrı dönüştürün. Her sürümü kendi arka planında kontrol edin; saydamlık her ikisinde de temiz olmalıdır.</p>\n<h2 id=\"webp-for-app-icons\">Uygulama simgeleri için WebP</h2>\n<p>Uygulama simgeleri genellikle birçok boyutta gerekir. Kaynak PNG'yi her boyutta WebP'ye dönüştürün; tutarlı kalite ayarı kullanın.</p>\n<p>Küçük simgelerde WebP kazancı az olabilir. 16x16 gibi minik simgelerde PNG bazen daha küçüktür; boyutları karşılaştırıp küçük olanı seçin.</p>\n<p>Uygulama mağazaları kendi formatlarını isteyebilir. Mağaza listesi için istenen formatı kullanın; WebP'yi uygulama içi görsellerde değerlendirin.</p>\n<h2 id=\"webp-for-blog-images\">Blog görselleri için WebP</h2>\n<p>Blog yazılarındaki görseller WebP ile belirgin hafifler. On görselli bir yazı, toplamda birkaç MB kazanabilir.</p>\n<p>Blog görselleri için yüzde 80 kalite yeterlidir. Okur farkı görmez ama sayfa hızlı açılır; bu da okurun sayfada kalmasını sağlar.</p>\n<p>Eski yazılardaki PNG'leri de dönüştürün. Toplu dönüştürmeyle arşivi bir seferde hafifletebilirsiniz; yalnızca dosya yollarını güncellemeyi unutmayın.</p>\n<h2 id=\"webp-for-ecommerce\">E-ticaret için WebP</h2>\n<p>Ürün görselleri e-ticaret sitelerinin en ağır yüküdür. WebP, ürün sayfalarını hızlandırır ve hızlı sayfalar daha çok satış getirir.</p>\n<p>Ürün fotoğraflarında kaliteyi yüzde 80-85 tutun. Müşteri ürünü net görmelidir; bulanık ürün fotoğrafı güven kaybettirir.</p>\n<p>Küçük resim ve büyük görsel için ayrı kalite kullanın. Küçük resimde yüzde 75 yeterli olurken, yakınlaştırılan büyük görselde yüzde 85 daha güvenlidir.</p>\n<h2 id=\"webp-for-social-graphics\">Sosyal medya görselleri için WebP</h2>\n<p>Sosyal medya platformları yüklenen görseli genellikle kendi formatına çevirir. Yine de WebP yüklemek, yükleme süresini kısaltır.</p>\n<p>Platformun istediği boyuta dikkat edin. Yanlış boyutlu görsel kırpılır; WebP burada boyut değil, yalnızca dosya ağırlığı kazandırır.</p>\n<p>Kapak ve profil görsellerinde kaliteyi yüksek tutun. Bu görseller markanızı temsil eder; yüzde 85-90 güvenli bir aralıktır.</p>\n<p>Özetle: saydam PNG'ler için WebP neredeyse her zaman kazandırır. Dönüştürmek için <a href=\"/tr/png-webp-ye-donustur\">PNG'den WebP'ye aracını</a> açın; adımlar için <a href=\"/tr/blog/png-webp-ye-nasil-donusturulur\">PNG WebP'ye nasıl dönüştürülür</a> yazısına bakın. Karşılaştırma için <a href=\"/tr/blog/png-vs-webp\">PNG ve WebP karşılaştırması</a> işinize yarar; saydamlık gerekmiyorsa <a href=\"/tr/png-jpg-ye-donustur\">PNG'den JPG'ye dönüştürücü</a> de bir seçenektir.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"PNG'yi WebP'ye dönüştürmek saydam arka planları gerçekten korur mu?","answer":"Evet. WebP, PNG gibi alfa kanalını destekler; saydam arka planlı bir logo dönüştürmeden sonra da saydam kalır. Yine de indirmeden önce önizlemede köşelerin temiz kaldığını kontrol edin; saydamlık çoğu durumda sorunsuz korunur."},{"question":"Aynı görselde WebP, PNG'den ne kadar daha küçük olur?","answer":"Genellikle yüzde 25 ila 35 daha küçüktür. 1 MB'lık bir PNG çoğunlukla 650-750 KB'lık bir WebP olur. Düz renkli logolar ve simgeler yüzde 50'den fazla küçülebilir; karmaşık, fotoğraf benzeri PNG'lerde kazanç daha azdır."},{"question":"Saydam PNG logolar için en iyi kalite ayarı hangisi?","answer":"Yüzde 85 civarı en iyi dengedir. Keskin kenarlar korunur, saydamlık sağlam kalır ve dosya PNG'den çok daha küçük olur. Marka logolarında yüzde 90'a çıkmak güvenlidir; yüzde 80'in altına inmek kenarlarda bozulma yapabilir."},{"question":"Bir simge setinin tamamını PNG'den WebP'ye aynı anda dönüştürebilir miyim?","answer":"Evet. Tüm PNG'leri aynı anda yükleyip tek seferde dönüştürebilirsiniz. Tutarlılık için bütün simgelerde aynı kalite ayarını kullanın ve dosya adlarını aynı tutup yalnızca uzantıyı değiştirin; referansları güncellemek böylece kolaylaşır."},{"question":"Web sitesi ana görselleri için WebP, PNG'den daha mı iyi?","answer":"Evet, çoğu durumda. Büyük bir PNG ana görsel WebP olarak yarıya inebilir ve sayfa belirgin biçimde hızlı yüklenir. Yüzde 80-85 kalite yeterlidir; çok eski tarayıcılar için picture öğesiyle JPG yedeği sunmak riski ortadan kaldırır."},{"question":"Dönüştürdüğüm WebP neden orijinal PNG'den daha büyük çıktı?","answer":"Çok küçük dosyalarda WebP'nin başlık bilgisi PNG'yi geçebilir; birkaç KB'lık simgelerde bu normaldir. Gürültülü, grenli PNG'ler de kötü sıkışır. Dönüştürülen dosya orijinalden büyükse PNG'yi saklayın; her dosyada kazanç olmaz."}];
